const player=character(0x4c8c6b,true);player.x=clamp(Number(state.position?.x)||-5,-10,10);player.z=clamp(Number(state.position?.z)||1.8,-7.4,7.5);player.bag=state.bag;player.root.position.set(player.x,.17,player.z);const playerLabel=label('SEN',player.x,2.1,player.z,'player-label');
const customers=[],workers=[];let cashierModel=null;const customerColors=[0xd5a263,0x7c98b1,0xcf8272,0xa1ad7b,0xc3a6c9,0x91b9ac];
// Grid navigation keeps customers, employees and click-to-walk clear of furniture.
const GRID=.45,MINX=-10,MINZ=-7.7,NX=45,NZ=40;
function blocked(x,z,r=.26){if(x<-10.15||x>10.15||z<-7.8||z>10.5)return true;return obstacles.some(o=>Math.abs(x-o.x)<o.w/2+r&&Math.abs(z-o.z)<o.d/2+r)}
function nearestCell(x,z){let ix=clamp(Math.round((x-MINX)/GRID),0,NX-1),iz=clamp(Math.round((z-MINZ)/GRID),0,NZ-1);if(!blocked(MINX+ix*GRID,MINZ+iz*GRID))return iz*NX+ix;for(let r=1;r<9;r++){for(let dz=-r;dz<=r;dz++)for(let dx=-r;dx<=r;dx++){const xx=ix+dx,zz=iz+dz;if(xx>=0&&xx<NX&&zz>=0&&zz<NZ&&!blocked(MINX+xx*GRID,MINZ+zz*GRID))return zz*NX+xx;}}return iz*NX+ix}
function pathTo(a,x,z){const start=nearestCell(a.x,a.z),goal=nearestCell(x,z);if(start===goal){a.path=blocked(x,z)?[]:[{x,z}];return}const total=NX*NZ,score=new Float32Array(total).fill(Infinity),came=new Int32Array(total).fill(-1),closed=new Uint8Array(total),open=[start];score[start]=0;const gx=goal%NX,gz=Math.floor(goal/NX);let iterations=0;while(open.length&&iterations++<1800){let best=0,bestF=Infinity;for(let j=0;j<open.length;j++){const n=open[j],f=score[n]+Math.hypot(n%NX-gx,Math.floor(n/NX)-gz);if(f<bestF){bestF=f;best=j}}const current=open.splice(best,1)[0];if(current===goal){const path=[];let n=goal;while(n!==start&&n!==-1){path.push({x:MINX+(n%NX)*GRID,z:MINZ+Math.floor(n/NX)*GRID});n=came[n]}a.path=path.reverse();if(!blocked(x,z))a.path.push({x,z});return}closed[current]=1;const cx=current%NX,cz=Math.floor(current/NX);for(let dz=-1;dz<=1;dz++)for(let dx=-1;dx<=1;dx++){if(!dx&&!dz)continue;const xx=cx+dx,zz=cz+dz;if(xx<0||xx>=NX||zz<0||zz>=NZ)continue;const n=zz*NX+xx;if(closed[n]||blocked(MINX+xx*GRID,MINZ+zz*GRID))continue;if(dx&&dz&&(blocked(MINX+cx*GRID,MINZ+zz*GRID)||blocked(MINX+xx*GRID,MINZ+cz*GRID)))continue;const v=score[current]+(dx&&dz?1.414:1);if(v<score[n]){score[n]=v;came[n]=current;if(!open.includes(n))open.push(n)}}}a.path=[]}
function move(a,dx,dz,dt,speed){const len=Math.hypot(dx,dz);if(len<.01)return false;const step=Math.min(len,speed*dt),nx=a.x+dx/len*step,nz=a.z+dz/len*step;let moved=false;if(!blocked(nx,a.z)){a.x=nx;moved=true}if(!blocked(a.x,nz)){a.z=nz;moved=true}if(moved){const target=Math.atan2(dx,dz);let delta=(target-a.body.rotation.y+Math.PI*3)%(Math.PI*2)-Math.PI;a.body.rotation.y+=delta*Math.min(1,dt*13)}return moved}
function follow(a,dt,speed){if(!a.path.length)return false;const p=a.path[0],d=Math.hypot(p.x-a.x,p.z-a.z);if(d<.09){a.path.shift();return a.path.length?follow(a,dt,speed):false;}return move(a,p.x-a.x,p.z-a.z,dt,speed)}
function animateActor(a,dt){a.phase+=dt*(a.moving?12:2);const bob=a.moving?Math.abs(Math.sin(a.phase))*.055:Math.sin(a.phase)*.012;a.root.position.set(a.x,.17+bob,a.z);a.legs.forEach((l,i)=>l.rotation.x=a.moving?Math.sin(a.phase+i*Math.PI)*.55:0);a.arms.forEach((l,i)=>l.rotation.x=a.bag.length?-.8:(a.moving?Math.sin(a.phase+i*Math.PI)*-.4:0));a.carry.rotation.z=a.moving?Math.sin(a.phase)*.05:0;updateCarry(a)}
function near(a,p,r=.95){return Math.hypot(a.x-p.x,a.z-p.z)<r}
function addCustomer(){if(customers.length>=9)return;const available=stations.filter(s=>state.unlocked[s.type]);const st=available[Math.floor(Math.random()*available.length)];const a=character(customerColors[Math.floor(Math.random()*customerColors.length)]);a.x=2+Math.random()*.4;a.z=9.4;a.want=st.type;a.status='shopping';a.wait=0;a.checkout=0;a.bubble=label(goods[a.want].emoji,a.x,2.05,a.z);a.bubble.el.style.fontSize='13px';a.target=st.customerPoint;pathTo(a,a.target.x+(Math.random()-.5)*.8,a.target.z);customers.push(a)}
function ensureStaff(){if(state.cashier&&!cashierModel){cashierModel=character(0xd9ac68);cashierModel.x=-6.8;cashierModel.z=3.5;cashierModel.body.rotation.y=.5;animateActor(cashierModel,0);label('KASİYER',-6.8,1.95,3.5)}if(state.worker&&!workers.length){const a=character(0x7da0af,true);a.x=-4.3;a.z=2;a.task=null;a.cool=0;workers.push(a)}}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');toastTimer=4}
let audioCtx=null;
function sound(kind='pick'){if(!state.settings.sound)return;try{audioCtx??=new(window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.connect(g);g.connect(audioCtx.destination);const now=audioCtx.currentTime;const f=kind==='sale'?760:kind==='unlock'?440:520+Math.random()*90;o.type='sine';o.frequency.setValueAtTime(f,now);o.frequency.exponentialRampToValueAtTime(kind==='unlock'?1200:f*1.35,now+.12);g.gain.setValueAtTime(.035,now);g.gain.exponentialRampToValueAtTime(.001,now+.2);o.start();o.stop(now+.21);}catch(e){}}
function burst(x,y,z,color=0xf3c957,n=9){for(let i=0;i<n&&particles.length<100;i++){const m=ball(.065,color,x,y,z);m.castShadow=false;particles.push({m,vx:(Math.random()-.5)*3,vy:2+Math.random()*2,vz:(Math.random()-.5)*3,life:.8,total:.8})}}
function floating(txt,x,y,z){const el=document.createElement('span');el.className='float-text';el.textContent=txt;$('labels').appendChild(el);floaters.push({el,pos:new THREE.Vector3(x,y,z),life:1.3})}
function fly(type,from,to){if(particles.length>90)return;const m=product(type,scene,from.x,from.y,from.z,.8);particles.push({m,from:new THREE.Vector3(from.x,from.y,from.z),to:new THREE.Vector3(to.x,to.y,to.z),life:.32,total:.32,fly:true})}
function transferToBag(a,st){if(state.stocks[st.type]>0&&a.bag.length<(a===player?capacity():5)){state.stocks[st.type]--;a.bag.push(st.type);if(a===player){state.harvested++;sound();}fly(st.type,{x:st.x,y:1,z:st.z},{x:a.x,y:1.2,z:a.z});return true}return false}
function stockShelf(a,st){const idx=a.bag.indexOf(st.type);if(idx>=0&&state.shelves[st.type]<12){a.bag.splice(idx,1);state.shelves[st.type]++;state.stocked++;fly(st.type,{x:a.x,y:1.3,z:a.z},{x:st.x,y:1.4,z:0});if(a===player)sound();return true}return false}
function feedStation(a,st){const idx=a.bag.indexOf('tomato');if(st.type!=='tomato'&&idx>=0&&state.feed[st.type]<8){a.bag.splice(idx,1);state.feed[st.type]++;fly('tomato',{x:a.x,y:1.3,z:a.z},{x:st.x,y:1,z:st.z});if(a===player)sound();return true}return false}
let currentHint='';
function interact(){let hint='Üret, rafları doldur ve kasaya uğra.';for(const st of stations){if(near(player,st.point,.7)){if(!state.unlocked[st.type]){hint=`${goods[st.type].name} alanını “Marketini büyüt” menüsünden aç.`;continue}if(st.type!=='tomato'&&player.bag.includes('tomato')&&state.feed[st.type]<8){feedStation(player,st);hint=st.type==='juice'?'Domatesler makineye aktarılıyor.':'Domatesler yemliğe aktarılıyor.';}else if(transferToBag(player,st)){hint=`${goods[st.type].name} toplanıyor…`;}else if(player.bag.length>=capacity()){hint='Çantan dolu. Ürünleri uygun rafa taşı.';}else if(st.type!=='tomato'&&!state.feed[st.type]){hint=st.type==='juice'?'Makineye domates getir; meyve suyuna dönüşsün.':'Üretim için yemliğe domates getir.';}else hint='Ürünler hazırlanıyor. Birazdan hazır!';}if(state.unlocked[st.type]&&near(player,st.stockPoint,.7)){if(stockShelf(player,st))hint='Raflar tazeleniyor. Mis gibi!';else hint=state.shelves[st.type]>=12?'Bu raf dolu. Diğer işlere göz at.':`Bu rafa ${goods[st.type].name.toLocaleLowerCase('tr')} getir.`;}}
 if(near(player,tillPoint,1.4)){hint='Kasadasın. Müşterilerin alışverişi tamamlanıyor.';if(state.till>0){const amount=state.till;state.money+=amount;state.till=0;floating(`+${amount} ₺`,player.x,2,player.z);burst(player.x,1.2,player.z);sound('sale');}}
 if(near(player,binPoint,.6)&&player.bag.length){player.bag.pop();hint='Çantandaki fazla ürünler geri dönüştürülüyor.';}
 if(!state.harvested&&state.mission===0)hint='Domates bahçesinin önündeki halkaya yürü.';currentHint=hint;
}
function updateProduction(dt){for(const st of stations){if(!state.unlocked[st.type])continue;if(st.buildAnim!==undefined){st.buildAnim=Math.min(1,st.buildAnim+dt/0.65);const t=st.buildAnim-1;st.g.scale.setScalar(1+2.7*t*t*t+1.7*t*t);if(st.buildAnim===1)delete st.buildAnim;}const factor=1+state.upgrades.growth*.3;if(state.stocks[st.type]>=8)continue;if(st.type!=='tomato'&&state.feed[st.type]<=0)continue;st.timer+=dt*factor;const interval={tomato:1.5,egg:2.8,milk:3.5,juice:4}[st.type];if(st.timer>=interval){st.timer-=interval;if(st.type!=='tomato')state.feed[st.type]--;state.stocks[st.type]+=st.type==='egg'?2:1;state.stocks[st.type]=Math.min(8,state.stocks[st.type]);if(st.type==='egg')state.eggs+=2;}if(st.spinner)st.spinner.rotation.y+=dt*3;}}
function updateCustomers(dt){const queue=customers.filter(c=>c.status==='queue');for(const a of [...customers]){a.moving=follow(a,dt,1.65);if(a.status==='shopping'&&!a.path.length){a.wait+=dt;const st=stations.find(s=>s.type===a.want);if(state.shelves[a.want]>0){state.shelves[a.want]--;a.bag.push(a.want);a.status='queue';a.wait=0;a.bubble.el.textContent='✓';pathTo(a,-3.4+queue.length*.77,5.35);sound('pick');}else if(a.wait>35&&a.wait<36){a.bubble.el.textContent='…';}else if(a.wait>65){a.status='leaving';a.bubble.el.textContent='☁';pathTo(a,2,9.5);}}else if(a.status==='queue'){const index=queue.indexOf(a);const tx=-3.4+Math.max(index,0)*.77;if(Math.hypot(a.x-tx,a.z-5.35)>.22&&!a.path.length)pathTo(a,tx,5.35);if(index===0&&near(a,{x:-3.4,z:5.35},.5)&&(state.cashier||near(player,tillPoint,1.4))){a.checkout+=dt*(state.cashier?1.25:1);a.bubble.el.textContent=a.checkout>.6?'₺':'···';if(a.checkout>1.2){const value=productPrice(a.want);state.till+=value;state.sales++;state.earned+=value;a.status='leaving';a.bag=[];a.bubble.el.textContent='♥';a.bubble.el.style.color='#d17f6d';floating(`+${value} ₺`,-6,2.4,5.3);burst(-6,1.9,5.3,0xf4ce6b,5);sound('sale');pathTo(a,2,9.5);}}}else if(a.status==='leaving'&&!a.path.length){scene.remove(a.root);a.bubble.el.remove();labels.splice(labels.indexOf(a.bubble),1);customers.splice(customers.indexOf(a),1);continue}a.bubble.pos.set(a.x,2.05,a.z);animateActor(a,dt);}}
function updateWorkers(dt){for(const a of workers){a.cool-=dt;a.moving=follow(a,dt,2.5);if(a.path.length){animateActor(a,dt);continue}if(a.cool>0){animateActor(a,dt);continue}a.cool=.3;if(a.task){const st=a.task.st;if(a.task.kind==='stock'){if(!stockShelf(a,st)||!a.bag.includes(st.type))a.task=null;}else if(a.task.kind==='feed'){if(!feedStation(a,st)||!a.bag.includes('tomato'))a.task=null;}else{if(!transferToBag(a,st)||a.bag.length>=5)a.task=null;}}else{
 const carried=a.bag[0];if(carried){const hungry=stations.find(s=>s.type!=='tomato'&&state.unlocked[s.type]&&state.feed[s.type]<3&&state.shelves[s.type]<5);const st=carried==='tomato'&&hungry?hungry:stations.find(s=>s.type===carried);if(carried==='tomato'&&hungry){a.task={kind:'feed',st};pathTo(a,st.point.x,st.point.z)}else if(state.shelves[carried]<12){a.task={kind:'stock',st};pathTo(a,st.stockPoint.x,st.stockPoint.z)}else{a.bag.shift();}}
 else{const st=stations.filter(s=>state.unlocked[s.type]&&state.stocks[s.type]>0&&(state.shelves[s.type]<10||s.type==='tomato')).sort((a,b)=>state.shelves[a.type]-state.shelves[b.type])[0];if(st){a.task={kind:'collect',st};pathTo(a,st.point.x,st.point.z)}}}animateActor(a,dt);}}
const missions=[
 {title:'İlk hasadını topla',text:'Domates bahçesinin önündeki halkaya yürü. Olgun domatesler çantana dolsun.',count:()=>state.harvested,target:3,unit:'domates',reward:15},
 {title:'Rafın bereketlensin',text:'Domates rafının arkasına yürü. Çantandaki domatesler otomatik yerleşir.',count:()=>state.stocked,target:5,unit:'ürün',reward:20},
 {title:'İlk müşterilerin',text:'Kasanın arkasındaki halkada bekle. Alışverişleri tamamla, kazancını topla.',count:()=>state.sales,target:3,unit:'müşteri',reward:35},
 {title:'Kümese yer aç',text:'Marketini büyüt menüsünden kümesi aç. Tavuklar yeni bir gelir kapısı.',count:()=>+state.unlocked.egg,target:1,unit:'kümes',reward:30},
 {title:'Taptaze yumurtalar',text:'Tavuklara domates götür. Yemler yumurtaya dönüşsün; yumurtaları rafına taşı.',count:()=>state.eggs,target:4,unit:'yumurta',reward:35},
 {title:'Birlikte daha kolay',text:'Ekibin menüsünden kasiyer işe al. Sen üretime bakarken o kasayı yönetsin.',count:()=>+state.cashier,target:1,unit:'kasiyer',reward:40},
 {title:'Süt zamanı',text:'Süt çiftliğini aç. İneğine domates götür, sütleri toplayıp rafa yerleştir.',count:()=>+state.unlocked.milk,target:1,unit:'çiftlik',reward:50},
 {title:'Tazeliği şişele',text:'Meyve suyu makinesini aç. Domatesleri daha değerli bir ürüne dönüştür.',count:()=>+state.unlocked.juice,target:1,unit:'makine',reward:60},
 {title:'İşi ekibine bırak',text:'Bir raf görevlisi işe al. Üretim, yemleme ve raf doldurma işlerine yardım etsin.',count:()=>+state.worker,target:1,unit:'görevli',reward:70},
 {title:'Mahallenin favorisi',text:'Ürün akışını dengede tut. 40 mutlu müşteriyle marketini taçlandır.',count:()=>state.sales,target:40,unit:'müşteri',reward:150},
 {title:'Küçük market, büyük başarı',text:'Tüm üretim alanları senin! Yükseltmeleri tamamla ve yeni satış rekorları kır.',count:()=>Object.values(state.upgrades).reduce((a,b)=>a+b,0),target:16,unit:'yükseltme',reward:250}
];
function checkMission(){const m=missions[state.mission];if(m&&m.count()>=m.target){state.money+=m.reward;state.mission++;toast(`✦ ${m.title} tamamlandı! +${m.reward} ₺`);burst(player.x,2,player.z,0xf2ca64,18);sound('unlock');save();}}
function save(){if(resetting)return;state.bag=player.bag;state.position={x:player.x,z:player.z};try{localStorage.setItem(SAVE_KEY,JSON.stringify(state));storageOK=true}catch(e){storageOK=false}}
function refreshScene(){for(const st of stations){const on=state.unlocked[st.type];st.g.visible=on;st.locked.visible=!on;st.shelf.visible=on;st.shelfRing.visible=on;st.shelfLabel.el.style.display=on?'':'none';st.label.el.className='world-label'+(on?(near(player,st.point,.9)?' active':''):' locked');st.shelfLabel.el.className='world-label'+(near(player,st.stockPoint,.9)?' active':'');st.label.el.innerHTML=on?`${goods[st.type].emoji} ${st.type==='tomato'?'BAHÇE':st.type==='egg'?'KÜMES':st.type==='milk'?'SÜT ÇİFTLİĞİ':'MEYVE SUYU'}<small>${state.stocks[st.type]} HAZIR ${st.type==='tomato'?'':`· ${state.feed[st.type]} ${st.type==='juice'?'DOMATES':'YEM'}`}</small>`:`＋ ${st.type==='egg'?'KÜMES':st.type==='milk'?'SÜT ÇİFTLİĞİ':'MEYVE SUYU'}<small>${unlockCost(st.type)} ₺ · KİLİTLİ</small>`;st.shelfLabel.el.innerHTML=`${goods[st.type].emoji} ${state.shelves[st.type]}/12 <em>· ${productPrice(st.type)} ₺</em>`;st.shelfMeshes.forEach((p,i)=>p.visible=i<state.shelves[st.type]);st.stockMeshes.forEach((p,i)=>p.visible=st.type!=='tomato'&&i<state.stocks[st.type]);st.cropMeshes.forEach((p,i)=>{p.visible=i<state.stocks[st.type]});}
 tillLabel.el.innerHTML=`KASA <em>${state.till?`· ${state.till} ₺`:''}</em><small>${state.cashier?'KASİYER İŞ BAŞINDA':'BURADA BEKLE · SATIŞ YAP'}</small>`;tillCash.forEach((p,i)=>p.visible=state.till>i*10);ensureStaff();}
function updateUI(){const level=Math.min(5,1+Math.floor(state.mission/2));$('money').textContent=Math.floor(state.money).toLocaleString('tr-TR');$('level').textContent=`Seviye ${level}`;$('level-progress').style.width=`${Math.min(100,(state.mission/missions.length)*100)}%`;$('sales').textContent=`${state.sales} mutlu müşteri`;$('capacity').textContent=`${player.bag.length} / ${capacity()}`;const totals={};player.bag.forEach(k=>totals[k]=(totals[k]||0)+1);$('inventory-items').textContent=player.bag.length?Object.entries(totals).map(([k,n])=>`${goods[k].emoji} ${n}`).join('  '):'Hasat için hazırsın';$('hint').textContent=currentHint||'Domates bahçesine doğru yürü';$('team-count').textContent=state.worker&&state.cashier?'2 yardımcı iş başında':state.cashier||state.worker?'1 yardımcı iş başında':'Her büyük iş bir ekiple başlar';const m=missions[state.mission];if(m){$('mission-title').textContent=m.title;$('mission-text').textContent=m.text;$('mission-count').textContent=`${Math.min(m.target,m.count())} / ${m.target} ${m.unit}`;$('mission-reward').textContent=`+${m.reward} ₺`;$('mission-progress').style.width=`${Math.min(100,m.count()/m.target*100)}%`;}else{$('mission-title').textContent='Mahallenin yıldızı sensin!';$('mission-text').textContent='Bütün hedefler tamamlandı. Marketin açık; yeni kazanç rekorları seni bekliyor.';$('mission-count').textContent=`${state.sales} mutlu müşteri`;$('mission-reward').textContent='✦ TAMAMLANDI';$('mission-progress').style.width='100%'}$('sound').textContent=state.settings.sound?'♫':'♪';$('sound').setAttribute('aria-label',state.settings.sound?'Sesi kapat':'Sesi aç');$('sound').style.opacity=state.settings.sound?'1':'.6';$('pause').innerHTML=paused?'<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><path d="M7 4 20 12 7 20Z"/></svg>':'<svg viewBox="0 0 24 24" width="18" height="18" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"/><rect x="14" y="4" width="4" height="16" rx="1"/></svg>';$('pause').setAttribute('aria-label',paused?'Oyuna devam et':'Oyunu duraklat');document.querySelector('.save-dot').style.color=storageOK?'#97ae83':'#d29c68';$('upgrade-dot').style.opacity=state.money>=80?'1':'0';refreshScene();}
function unlockCost(type){return {egg:80,milk:180,juice:280}[type]||0}
const upgradeDefs={speed:{name:'Hafif adımlar',desc:'Yürüme hızın her seviyede %18 artar.',emoji:'👟',base:65},capacity:{name:'Büyük bir çanta',desc:'Her seviyede 3 ürün daha taşı.',emoji:'🎒',base:55},growth:{name:'Bereketli üretim',desc:'Tüm üretim alanları %30 hızlanır.',emoji:'🌱',base:90},value:{name:'Mahalle kalitesi',desc:'Bütün ürünlerin satış fiyatına +2 ₺.',emoji:'✦',base:120}};
function upgradeCost(k){return Math.round(upgradeDefs[k].base*Math.pow(1.7,state.upgrades[k]))}
function buy(type,key){let price=0;if(type==='unlock'){if(state.unlocked[key])return;const prereq=key==='milk'?'egg':key==='juice'?'milk':'tomato';if(!state.unlocked[prereq])return;price=unlockCost(key);}else if(type==='upgrade'){if(state.upgrades[key]>=4)return;price=upgradeCost(key);}else{if(state[key])return;price=key==='cashier'?110:210;}if(state.money<price){toast('Birkaç satış daha yap, sonra tekrar gel.');return}state.money-=price;if(type==='unlock'){state.unlocked[key]=true;const area=stations.find(s=>s.type===key);area.buildAnim=0;area.g.scale.setScalar(.1);toast(`${goods[key].emoji} Yeni alan açıldı! Üretim için domates götür.`);burst(stations.find(s=>s.type===key).x,1,-4.65,0xf0cb6d,25);}else if(type==='upgrade'){state.upgrades[key]++;toast('✦ Yükseltme tamamlandı!');}else{state[key]=true;toast(key==='cashier'?'Kasiyer iş başında! Kazancını kasadan toplamayı unutma.':'Raf görevlisi iş başında! Ürünleri toplar, yemler ve rafları doldurur.');}sound('unlock');ensureStaff();checkMission();save();updateUI();renderPanel();}
function row(emoji,name,desc,price,action,disabled=false,done=false){return `<div class="upgrade-row"><span class="upgrade-emoji">${emoji}</span><div class="upgrade-info"><h3>${name}</h3><p>${desc}</p></div><button class="buy-button" ${disabled||done?'disabled':''} data-action="${action}">${done?'✓ Açık':price}</button></div>`}
function renderPanel(){const c=$('panel-content');$('panel-eyebrow').textContent='BÜYÜK HAYALLERE KÜÇÜK ADIMLAR';if(modalMode==='upgrades'){$('panel-title').textContent='Marketini büyüt';$('panel-description').textContent=`Bugünün kazancı, yarının marketi. Bakiyen: ${state.money} ₺`;let html='';for(const k of ['egg','milk','juice']){const prereq=k==='milk'?'egg':k==='juice'?'milk':'tomato';html+=row(goods[k].emoji,k==='egg'?'Kümes':k==='milk'?'Süt çiftliği':'Meyve suyu makinesi',state.unlocked[prereq]?(k==='juice'?'Domates → meyve suyu · 30 ₺':'Domatesle besle, yeni ürününü sat.'):`Önce ${prereq==='egg'?'kümesi':'süt çiftliğini'} aç.`,`${unlockCost(k)} ₺`,`unlock:${k}`,!state.unlocked[prereq]||state.money<unlockCost(k),state.unlocked[k])}for(const [k,v]of Object.entries(upgradeDefs))html+=row(v.emoji,`${v.name} <small>· ${state.upgrades[k]}/4</small>`,v.desc,`${upgradeCost(k)} ₺`,`upgrade:${k}`,state.money<upgradeCost(k)||state.upgrades[k]>=4,state.upgrades[k]>=4);c.innerHTML=html;}
 else if(modalMode==='team'){$('panel-title').textContent='İyi işler, iyi bir ekiple.';$('panel-description').textContent='Tek seferlik işe al. Birlikte büyüyün.';c.innerHTML=row('🧑‍💼','Kasiyer','Kasayı otomatik yönetir. Biriken parayı almak için kasaya uğra.','110 ₺','staff:cashier',state.money<110,state.cashier)+row('🧑‍🌾','Raf görevlisi','Ürün toplar, hayvanları besler, makineye malzeme ve raflara ürün taşır.','210 ₺','staff:worker',state.money<210,state.worker);}
 else if(modalMode==='pause'){$('panel-eyebrow').textContent='KÜÇÜK BİR MOLA';$('panel-title').textContent='Marketin seni bekler.';$('panel-description').textContent='Oyun duraklatıldı. Her şey bıraktığın gibi.';c.innerHTML=`<div class="stats-grid"><div><b>${state.sales}</b><span>MUTLU MÜŞTERİ</span></div><div><b>${state.earned} ₺</b><span>TOPLAM SATIŞ</span></div><div><b>${Object.values(state.unlocked).filter(Boolean).length}/4</b><span>ÜRETİM ALANI</span></div></div><button class="primary-button" data-action="resume">İşin başına dön →</button>`;}
 else if(modalMode==='settings'){$('panel-eyebrow').textContent='KENDİ RİTMİNİ BUL';$('panel-title').textContent='Küçük ayarlar';$('panel-description').textContent='Sana en rahat gelen şekilde oyna.';c.innerHTML=`<div class="settings-row"><span>Oyun sesleri</span><button class="buy-button" data-action="sound">${state.settings.sound?'Açık ♫':'Kapalı ♪'}</button></div><div class="settings-row"><label for="quality">Görüntü kalitesi</label><select id="quality"><option value="auto">Otomatik</option><option value="high">Yüksek</option><option value="low">Performans</option></select></div><div class="help-grid"><div><b>Hareket:</b> WASD, ok tuşları, yere tıklama veya mobil joystick.</div><div><b>Üretim:</b> Halkanın içinde dur. Toplama, yemleme ve raf doldurma otomatiktir.</div><div><b>Satış:</b> Kasada bekle. Kasiyer aldığında biriken parayı kasadan topla.</div><div><b>Çanta:</b> Fazla ürünleri geri dönüşüm kutusunun yanında boşalt.</div><div><b>Kısayollar:</b> P duraklatır; Esc pencereyi kapatır.</div></div><p class="settings-note">${storageOK?'İlerlemen bu tarayıcıda otomatik kaydedilir.':'Tarayıcı kaydına erişilemiyor. Bu oturumdaki ilerleme kalıcı olmayabilir.'} Bu bağımsız uyarlama My Mini Mart’ın temel mekaniklerinden esinlenir. Oyun kodu ve 3B görseller bu proje için hazırlanmıştır.</p><div class="download-links"><a href="mini-mart-tek-dosya.html" download>Tek dosya HTML indir ↗</a><a href="mini-mart-kaynak-kodu.zip" download>Kaynak kodunu indir ↗</a></div><button class="primary-button danger" data-action="reset-confirm">Yeni başlangıç</button>`;$('quality').value=state.settings.quality;$('quality').onchange=e=>{state.settings.quality=e.target.value;applyQuality();save()};}
 else if(modalMode==='reset'){$('panel-title').textContent='Yeniden başlayalım mı?';$('panel-description').textContent='Bu tarayıcıdaki market kaydı silinir. Bu işlem geri alınamaz.';c.innerHTML='<button class="primary-button danger" data-action="reset">Evet, marketi sıfırla</button><button class="primary-button" style="margin-top:10px" data-action="cancel-reset">Marketimi koru</button>';}
}
let previousFocus=null;
function openPanel(mode){previousFocus=document.activeElement;keys.clear();joy.x=joy.y=0;$('stick').style.transform='';modalMode=mode;$('modal').hidden=false;renderPanel();$('close-panel').focus();}
function closePanel(){const wasPause=modalMode==='pause';modalMode='';$('modal').hidden=true;if(wasPause)paused=false;previousFocus?.focus?.();updateUI()}
$('upgrades').onclick=()=>openPanel('upgrades');$('team').onclick=()=>openPanel('team');$('settings').onclick=()=>openPanel('settings');$('close-panel').onclick=closePanel;
function togglePause(){if(modalMode==='pause'){closePanel();return}paused=!paused;if(paused)openPanel('pause');updateUI()}
$('pause').onclick=togglePause;$('sound').onclick=()=>{state.settings.sound=!state.settings.sound;sound();save();updateUI()};$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closePanel();const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a.includes(':')){const [t,k]=a.split(':');buy(t,k)}else if(a==='resume')closePanel();else if(a==='sound'){$('sound').click();renderPanel()}else if(a==='reset-confirm'){modalMode='reset';renderPanel()}else if(a==='cancel-reset'){modalMode='settings';renderPanel()}else if(a==='reset'){resetting=true;state=fresh();try{localStorage.setItem(SAVE_KEY,JSON.stringify(state))}catch(e){}location.reload()}});
const raycaster=new THREE.Raycaster(),ndc=new THREE.Vector2(),floorPlane=new THREE.Plane(new THREE.Vector3(0,1,0),-.16),hit=new THREE.Vector3();const destinationRing=ring(0,0,0xffffff,.35);destinationRing.visible=false;
let pointerStart=null;
$('world').addEventListener('pointerdown',e=>{if(modalMode)return;pointerStart={x:e.clientX,y:e.clientY};$('world').focus();if(state.settings.sound&&audioCtx?.state==='suspended')audioCtx.resume()});
$('world').addEventListener('pointerup',e=>{if(!pointerStart||modalMode||paused)return;if(Math.hypot(e.clientX-pointerStart.x,e.clientY-pointerStart.y)>16)return;pointerStart=null;ndc.set(e.clientX/innerWidth*2-1,-e.clientY/innerHeight*2+1);raycaster.setFromCamera(ndc,camera);if(raycaster.ray.intersectPlane(floorPlane,hit)){let x=clamp(hit.x,-10,10),z=clamp(hit.z,-7.5,7.7);for(const st of stations){if(Math.abs(x-st.x)<1.9&&Math.abs(z-st.z)<1.7){x=st.point.x;z=st.point.z;if(!state.unlocked[st.type])openPanel('upgrades');}else if(Math.abs(x-st.x)<1.5&&Math.abs(z)<1.3){x=st.stockPoint.x;z=st.stockPoint.z;}}if(Math.abs(x+6)<2&&Math.abs(z-5.3)<1.5){x=tillPoint.x;z=tillPoint.z;}pathTo(player,x,z);destinationRing.position.set(x,.2,z);destinationRing.visible=true;}});
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(k==='escape'){if(modalMode)closePanel();else togglePause();return}if(k==='p'&&!e.repeat){if(!modalMode||modalMode==='pause')togglePause();return}if(modalMode){if(e.key==='Tab'){const f=[...$('modal').querySelectorAll('button:not(:disabled),select')];if(e.shiftKey&&document.activeElement===f[0]){e.preventDefault();f.at(-1).focus()}else if(!e.shiftKey&&document.activeElement===f.at(-1)){e.preventDefault();f[0].focus()}}return}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright',' '].includes(k)){e.preventDefault();keys.add(k)}});
window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>{keys.clear();joy.x=joy.y=0});document.addEventListener('visibilitychange',()=>{keys.clear();joy.x=joy.y=0;save();last=performance.now()});window.addEventListener('pagehide',save);
let joyId=null;function joyMove(e){if(joyId!==e.pointerId)return;const rect=$('joystick').getBoundingClientRect(),dx=e.clientX-rect.left-rect.width/2,dy=e.clientY-rect.top-rect.height/2,d=Math.max(30,Math.hypot(dx,dy));joy.x=dx/d;joy.y=dy/d;$('stick').style.transform=`translate(${joy.x*27}px,${joy.y*27}px)`;player.path=[];e.preventDefault()}
$('joystick').addEventListener('pointerdown',e=>{joyId=e.pointerId;$('joystick').setPointerCapture(e.pointerId);joyMove(e)});$('joystick').addEventListener('pointermove',joyMove);for(const event of ['pointerup','pointercancel','lostpointercapture'])$('joystick').addEventListener(event,()=>{joyId=null;joy.x=joy.y=0;$('stick').style.transform='' });
function applyQuality(){const low=state.settings.quality==='low'||(state.settings.quality==='auto'&&softwareGPU);renderer.setPixelRatio(Math.min(devicePixelRatio,low?1:state.settings.quality==='high'?2:1.25)*renderScale);renderer.shadowMap.enabled=!low;renderer.setSize(innerWidth,innerHeight);}
const cameraFocus=new THREE.Vector3();
function resize(){const w=innerWidth,h=innerHeight,aspect=w/h;let view=aspect<.8?21/aspect:aspect<1.25?25:24;camera.left=-view*aspect/2;camera.right=view*aspect/2;camera.top=view/2;camera.bottom=-view/2;camera.zoom=aspect<.8?1.12:1;cameraFocus.set(w<700?player.x:0,0,w<700?player.z-1:0);camera.position.set(24+cameraFocus.x,33,29+cameraFocus.z);camera.lookAt(cameraFocus);camera.updateProjectionMatrix();applyQuality()}
window.addEventListener('resize',resize);resize();
const projectVec=new THREE.Vector3();function place(el,pos){projectVec.copy(pos).project(camera);el.style.left=((projectVec.x*.5+.5)*innerWidth)+'px';el.style.top=((-projectVec.y*.5+.5)*innerHeight)+'px';}
function tick(now){requestAnimationFrame(tick);const rawDt=(now-last)/1000;last=now;const dt=Math.min(rawDt,.05);if(document.hidden)return;const running=!paused&&!modalMode;if(running){time+=dt;spawnTimer-=dt;if(spawnTimer<0){addCustomer();spawnTimer=4.5+Math.random()*2.2;}let sx=(keys.has('d')||keys.has('arrowright')?1:0)-(keys.has('a')||keys.has('arrowleft')?1:0)+joy.x;let sy=(keys.has('s')||keys.has('arrowdown')?1:0)-(keys.has('w')||keys.has('arrowup')?1:0)+joy.y;const n=Math.hypot(sx,sy);if(n>.05){player.path=[];destinationRing.visible=false;sx/=Math.max(1,n);sy/=Math.max(1,n);player.moving=move(player,sx*.77+sy*.64,-sx*.64+sy*.77,dt,3.8*(1+state.upgrades.speed*.18));}else{player.moving=follow(player,dt,3.8*(1+state.upgrades.speed*.18));if(!player.path.length)destinationRing.visible=false;}animateActor(player,dt);updateProduction(dt);updateCustomers(dt);updateWorkers(dt);if(cashierModel)animateActor(cashierModel,dt);interactionTimer+=dt;if(interactionTimer>.22){interactionTimer=0;interact();checkMission();}saveTimer+=dt;if(saveTimer>4){saveTimer=0;save();}for(let i=0;i<plantAnimations.length;i++){const g=plantAnimations[i];g.rotation.z=Math.sin(time*1.6+i*.9)*.022;}for(let i=0;i<animalAnimations.length;i++){const g=animalAnimations[i];g.rotation.y=Math.sin(time*.6+i*2)*.13;g.position.y=(i===2?.45:.55)+Math.sin(time*2+i)*.025;}}
 for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.life-=dt;if(p.life<=0){scene.remove(p.m);particles.splice(i,1);continue}if(p.fly){const t=1-p.life/p.total;p.m.position.lerpVectors(p.from,p.to,t);p.m.position.y+=Math.sin(t*Math.PI)*.8;p.m.rotation.y+=dt*5;}else{p.vy-=dt*8;p.m.position.x+=p.vx*dt;p.m.position.y+=p.vy*dt;p.m.position.z+=p.vz*dt;p.m.scale.setScalar(Math.min(1,p.life*3));}}
 for(let i=floaters.length-1;i>=0;i--){const f=floaters[i];f.life-=dt;f.pos.y+=dt*.8;f.el.style.opacity=String(Math.min(1,f.life*2));place(f.el,f.pos);if(f.life<=0){f.el.remove();floaters.splice(i,1)}}
 if(innerWidth<700){const smooth=1-Math.exp(-dt*5);cameraFocus.x+=(player.x-cameraFocus.x)*smooth;cameraFocus.z+=(player.z-1-cameraFocus.z)*smooth;camera.position.set(24+cameraFocus.x,33,29+cameraFocus.z);camera.lookAt(cameraFocus);}
 playerLabel.pos.set(player.x,1.97+player.bag.length*.1,player.z);for(const l of labels)place(l.el,l.pos);destinationRing.scale.setScalar(1+Math.sin(time*5)*.12);uiTimer+=dt;if(uiTimer>.15){uiTimer=0;updateUI()}if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('toast').classList.remove('show')}renderer.render(scene,camera);
 if(state.settings.quality==='auto'&&running&&rawDt<.3){frameCount++;dtTotal+=rawDt;if(frameCount>=45){if(dtTotal/frameCount>.032&&renderScale>.7){renderScale=.7;renderer.shadowMap.enabled=false;renderer.setPixelRatio(1);renderer.setSize(innerWidth,innerHeight)}frameCount=0;dtTotal=0}}
}
const dynamic=new Set([...plantAnimations,...animalAnimations,player.root,player.carry,destinationRing,tillRing,queueRing,binRing,...tillCash,...stations.flatMap(s=>[s.ring,s.shelfRing,s.spinner,...s.cropMeshes,...s.stockMeshes,...s.shelfMeshes]).filter(Boolean)]);batchStatic(scene,dynamic);
ensureStaff();refreshScene();updateUI();renderer.render(scene,camera);$('loading').style.opacity='0';setTimeout(()=>$('loading').remove(),550);requestAnimationFrame(tick);
