window.miniMart={snapshot:()=>JSON.parse(JSON.stringify({...state,position:{x:player.x,z:player.z},customers:customers.map(c=>({x:c.x,z:c.z,status:c.status,want:c.want,path:c.path.length})),workerTasks:workers.map(w=>({task:w.task?.kind,product:w.task?.st.type,bag:w.bag.slice()})),renderer:{calls:renderer.info.render.calls,triangles:renderer.info.render.triangles},paused:paused||!!modalMode})),worldToScreen:(x,z,y=.16)=>{const v=new THREE.Vector3(x,y,z).project(camera);return {x:(v.x*.5+.5)*innerWidth,y:(-v.y*.5+.5)*innerHeight}}};
